import pandas as pd
import numpy as np

# Ensure a copy of the DataFrame is used to avoid SettingWithCopyWarning
df_processed = df.copy()

# Convert 'BILL_DATE' to datetime.
if 'BILL_DATE' in df_processed.columns:
    df_processed['BILL_DATE'] = pd.to_datetime(df_processed['BILL_DATE'], format='%d-%m-%Y', errors='coerce')
    if df_processed['BILL_DATE'].isnull().all() and pd.api.types.is_numeric_dtype(df_processed['BILL_DATE']):
        df_processed['BILL_DATE'] = pd.to_datetime(df_processed['BILL_DATE'], unit='ms', errors='coerce')
        if df_processed['BILL_DATE'].isnull().all():
            df_processed['BILL_DATE'] = pd.to_datetime(df_processed['BILL_DATE'], unit='s', errors='coerce')
else:
    df_processed['BILL_DATE'] = pd.NaT

numeric_cols = ['QTY_ACCEPTED', 'PRICE', 'LINE_VALUE']
for col in numeric_cols:
    if col in df_processed.columns:
        df_processed[col] = pd.to_numeric(df_processed[col], errors='coerce')

essential_cols = ['ITEM_NAME', 'QTY_ACCEPTED', 'PRICE', 'LINE_VALUE', 'BILL_DATE']
df_processed.dropna(subset=essential_cols, inplace=True)

if 'CANCEL_FLAG' in df_processed.columns:
    df_processed = df_processed[~df_processed['CANCEL_FLAG'].astype(str).str.lower().str.contains('y|true|yes', na=False)]

if df_processed.empty:
    output_df = None
else:
    if 'ITEM_NAME' in df_processed.columns and 'LINE_VALUE' in df_processed.columns:
        # Calculate total value across all items for percentage calculation
        total_overall_value = df_processed['LINE_VALUE'].sum()

        item_value = df_processed.groupby('ITEM_NAME')['LINE_VALUE'].sum().sort_values(ascending=False)
        top_20_items = item_value.head(20).index
        df_top20 = df_processed[df_processed['ITEM_NAME'].isin(top_20_items)].copy()
        if df_top20.empty:
            output_df = None
        else:
            insights = []
            for item_name in top_20_items:
                item_df = df_top20[df_top20['ITEM_NAME'] == item_name].copy()
                if item_df.empty:
                    continue
                total_qty = item_df['QTY_ACCEPTED'].sum()
                total_value = item_df['LINE_VALUE'].sum()
                # Calculate percentage contribution to total value
                percentage_contribution = (total_value / total_overall_value) * 100
                avg_unit_price_overall = item_df['PRICE'].mean()

                purchase_frequency_monthly_avg = np.nan
                freq_obs = 'N/A (No valid dates or data)'
                if not item_df['BILL_DATE'].isnull().all() and len(item_df) > 0:
                    item_df_freq = item_df.set_index('BILL_DATE')
                    monthly_purchases_count = item_df_freq.resample('ME').size()
                    active_months_purchases = monthly_purchases_count[monthly_purchases_count > 0]
                    if not active_months_purchases.empty:
                        purchase_frequency_monthly_avg = active_months_purchases.mean()
                        freq_obs = 'Consistent'
                        if active_months_purchases.std() / active_months_purchases.mean() > 1.0:
                            freq_obs = 'Inconsistent/Volatile'
                        min_date = item_df['BILL_DATE'].min()
                        max_date = item_df['BILL_DATE'].max()
                        if pd.notna(min_date) and pd.notna(max_date):
                            total_span_months = (max_date.to_period('M') - min_date.to_period('M')).n + 1
                            if total_span_months > 6 and len(active_months_purchases) / total_span_months < 0.5:
                                freq_obs = 'Sporadic/Gaps'
                        if item_df['BILL_DATE'].dt.month.nunique() < 6 and item_df['BILL_DATE'].dt.year.nunique() > 1:
                            freq_obs = 'Potentially Seasonal'
                    else:
                        freq_obs = 'No purchases in valid date range'
                else:
                    freq_obs = 'No valid dates for frequency analysis'

                price_trend_monthly_list = []
                price_fluctuation_std = np.nan
                price_trend_observation = 'N/A (No valid dates or data)'

                if not item_df['BILL_DATE'].isnull().all() and len(item_df) > 0:
                    monthly_avg_price = item_df.set_index('BILL_DATE').resample('ME')['PRICE'].mean().dropna()
                    if not monthly_avg_price.empty:
                        price_trend_monthly_list = monthly_avg_price.tolist()
                        price_fluctuation_std = monthly_avg_price.std()
                        if len(monthly_avg_price) > 1:
                            first_price = monthly_avg_price.iloc[0]
                            last_price = monthly_avg_price.iloc[-1]
                            price_change_percent = ((last_price - first_price) / first_price) * 100 if first_price != 0 else 0
                            if price_change_percent > 5:
                                price_trend_observation = 'Increasing'
                            elif price_change_percent < -5:
                                price_trend_observation = 'Declining'
                            elif price_fluctuation_std / monthly_avg_price.mean() > 0.1:
                                price_trend_observation = 'Volatile'
                            else:
                                price_trend_observation = 'Stable'
                        elif len(monthly_avg_price) == 1:
                            price_trend_observation = 'Single purchase/Stable (no trend)'
                        else:
                            price_trend_observation = 'No price data over time'
                    else:
                        price_trend_observation = 'No price data over time'
                else:
                    price_trend_observation = 'No valid dates for price trend analysis'

                high_value_purchase_obs = 'None'
                if not item_df['BILL_DATE'].isnull().all() and len(item_df) > 0:
                    Q1 = item_df['LINE_VALUE'].quantile(0.25)
                    Q3 = item_df['LINE_VALUE'].quantile(0.75)
                    IQR = Q3 - Q1
                    upper_bound = Q3 + 1.5 * IQR
                    high_value_purchases = item_df[item_df['LINE_VALUE'] > upper_bound].sort_values(by='BILL_DATE')
                    if not high_value_purchases.empty:
                        found_short_period = False
                        if len(high_value_purchases) > 1:
                            for i in range(len(high_value_purchases) - 1):
                                time_diff = (high_value_purchases.iloc[i+1]['BILL_DATE'] - high_value_purchases.iloc[i]['BILL_DATE']).days
                                if pd.notna(time_diff) and 0 <= time_diff <= 7:
                                    high_value_purchase_obs = 'Yes (Multiple high-value purchases in short period)'
                                    found_short_period = True
                                    break
                        if not found_short_period:
                            high_value_purchase_obs = 'Yes (Individual high-value outlier purchases)'
                else:
                    high_value_purchase_obs = 'No valid dates for high-value purchase analysis'

                insights.append({
                    'Item Name': item_name,
                    'Total Quantity Purchased': total_qty,
                    'Total Purchase Value': total_value,
                    'Percentage Contribution to Total Value (%)': percentage_contribution,
                    'Average Unit Price (Overall)': avg_unit_price_overall,
                    'Purchase Frequency (Monthly Avg)': purchase_frequency_monthly_avg,
                    'Price Trend (Monthly Avg List)': price_trend_monthly_list,
                    'Price Fluctuation (Std Dev)': price_fluctuation_std,
                    'Price Trend Observation': price_trend_observation,
                    'Frequency Observation': freq_obs,
                    'High Value Purchase Observation': high_value_purchase_obs
                })

            output_df = pd.DataFrame(insights)
            output_df = output_df.sort_values(by=['Total Purchase Value', 'Total Quantity Purchased'], ascending=[False, False])
    else:
        output_df = None

