import pandas as pd

# Create a copy of the DataFrame to avoid modifying the original
df = df.copy()

# --- 1. Data Cleaning and Preprocessing ---
date_cols = ['BILL_DATE', 'PARTY_BILLDATE', 'VOU_DATE', 'GRN_DATE', 'PO_DATE']
for col in date_cols:
    if col in df.columns:
        df.loc[:, col] = pd.to_datetime(df[col], errors='coerce')

if 'LINE_VALUE' in df.columns:
    df.loc[:, 'LINE_VALUE'] = pd.to_numeric(df['LINE_VALUE'], errors='coerce')
if 'QTY_ACCEPTED' in df.columns:
    df.loc[:, 'QTY_ACCEPTED'] = pd.to_numeric(df['QTY_ACCEPTED'], errors='coerce')

critical_cols_for_dropna = ['VOU_DATE', 'LINE_VALUE', 'QTY_ACCEPTED']
df.dropna(subset=[col for col in critical_cols_for_dropna if col in df.columns], inplace=True)

if 'GRN_DATE' in df.columns and 'PO_DATE' in df.columns and not df['GRN_DATE'].isna().all() and not df['PO_DATE'].isna().all():
    df.loc[:, 'Lead Time Days'] = (df['GRN_DATE'] - df['PO_DATE']).dt.days
else:
    df.loc[:, 'Lead Time Days'] = pd.NA

summary_dfs = []

granularities = {
    'Yearly': lambda df_col: df_col.dt.to_period('Y'),
    'Quarterly': lambda df_col: df_col.dt.to_period('Q'),
    'Monthly': lambda df_col: df_col.dt.to_period('M'),
    'Weekly': lambda df_col: df_col.dt.to_period('W')
}

required_cols = ['VOU_DATE', 'LINE_VALUE', 'QTY_ACCEPTED', 'SUPPLIER_NAME', 'ITEM_NAME']
if all(col in df.columns for col in required_cols) and not df['VOU_DATE'].isna().all():
    for period_type, period_func in granularities.items():
        if not df['VOU_DATE'].isna().all():
            df['Period'] = period_func(df['VOU_DATE'])

            purchase_trends = df.groupby('Period').agg(
                Total_Purchase_Value=('LINE_VALUE', 'sum'),
                Total_Quantity=('QTY_ACCEPTED', 'sum')
            ).reset_index()
            purchase_trends['Period_Type'] = period_type

            supplier_perf = df.groupby(['Period', 'SUPPLIER_NAME']).agg(
                Supplier_Revenue=('LINE_VALUE', 'sum'),
                Supplier_Quantity=('QTY_ACCEPTED', 'sum')
            ).reset_index()

            if not supplier_perf.empty:
                top_supplier_revenue = supplier_perf.loc[supplier_perf.groupby('Period')['Supplier_Revenue'].idxmax()]
                top_supplier_revenue = top_supplier_revenue.rename(columns={
                    'SUPPLIER_NAME': 'Top_Supplier_Revenue',
                    'Supplier_Revenue': 'Top_Supplier_Revenue_Value'
                })[['Period', 'Top_Supplier_Revenue', 'Top_Supplier_Revenue_Value']]

                top_supplier_quantity = supplier_perf.loc[supplier_perf.groupby('Period')['Supplier_Quantity'].idxmax()]
                top_supplier_quantity = top_supplier_quantity.rename(columns={
                    'SUPPLIER_NAME': 'Top_Supplier_Quantity',
                    'Supplier_Quantity': 'Top_Supplier_Quantity_Value'
                })[['Period', 'Top_Supplier_Quantity', 'Top_Supplier_Quantity_Value']]

                purchase_trends = pd.merge(purchase_trends, top_supplier_revenue, on='Period', how='left')
                purchase_trends = pd.merge(purchase_trends, top_supplier_quantity, on='Period', how='left')

            product_perf = df.groupby(['Period', 'ITEM_NAME']).agg(
                Product_Revenue=('LINE_VALUE', 'sum'),
                Product_Quantity=('QTY_ACCEPTED', 'sum')
            ).reset_index()

            if not product_perf.empty:
                best_product_revenue = product_perf.loc[product_perf.groupby('Period')['Product_Revenue'].idxmax()]
                best_product_revenue = best_product_revenue.rename(columns={
                    'ITEM_NAME': 'Best_Product_Revenue',
                    'Product_Revenue': 'Best_Product_Revenue_Value'
                })[['Period', 'Best_Product_Revenue', 'Best_Product_Revenue_Value']]

                best_product_quantity = product_perf.loc[product_perf.groupby('Period')['Product_Quantity'].idxmax()]
                best_product_quantity = best_product_quantity.rename(columns={
                    'ITEM_NAME': 'Best_Product_Quantity',
                    'Product_Quantity': 'Best_Product_Quantity_Value'
                })[['Period', 'Best_Product_Quantity', 'Best_Product_Quantity_Value']]

                purchase_trends = pd.merge(purchase_trends, best_product_revenue, on='Period', how='left')
                purchase_trends = pd.merge(purchase_trends, best_product_quantity, on='Period', how='left')

            if 'Lead Time Days' in df.columns and not df['Lead Time Days'].isna().all():
                lead_time_analysis = df.groupby('Period').agg(
                    Average_Lead_Time_Days=('Lead Time Days', 'mean')
                ).reset_index()
                purchase_trends = pd.merge(purchase_trends, lead_time_analysis, on='Period', how='left')

            summary_dfs.append(purchase_trends)
else:
    summary_dfs = []

if summary_dfs:
    output_df = pd.concat(summary_dfs, ignore_index=True)
    output_df['Period'] = output_df['Period'].astype(str)
else:
    output_df = None

if 'Period' in df.columns:
    df.drop(columns=['Period'], inplace=True)

