import pandas as pd

# --- Base aggregation ---
product_summary = (
    df.groupby(['PRODUCT_NAME']).agg(
        Total_Including_Value=("ITEM_VALUE_INCL_TAX", 'sum'),
        Total_quantity=("NU_PRODUCT_QUANTITY", "sum")
    ).reset_index().round(1)
)

# --- Sort by Value then Quantity ---
product_summary = product_summary.sort_values(
    by=["Total_Including_Value", "Total_quantity"], 
    ascending=[False, False]
)

# --- Select Top 10 and Bottom 10 ---
top_10 = product_summary.head(10)
bottom_10 = product_summary.tail(10)
product_summary = pd.concat([top_10, bottom_10]).reset_index(drop=True)

# --- Helper to compute percentage shares ---
def make_share_dict(subdf, key_col, value_col="ITEM_VALUE_INCL_TAX"):
    total = subdf[value_col].sum()
    return {
        str(k): round(v / total * 100, 2)
        for k, v in subdf.groupby(key_col)[value_col].sum().items()
        if total > 0
    }

# --- Add Region, Zone, Sales Exec % per product ---
product_summary["regions_per_percentage"] = product_summary["PRODUCT_NAME"].apply(
    lambda p: make_share_dict(df[df["PRODUCT_NAME"] == p], "REGION")
)

product_summary["zones_per_percentage"] = product_summary["PRODUCT_NAME"].apply(
    lambda p: make_share_dict(df[df["PRODUCT_NAME"] == p], "ZONE")
)

product_summary["sales_executives_per_percentage"] = product_summary["PRODUCT_NAME"].apply(
    lambda p: make_share_dict(df[df["PRODUCT_NAME"] == p], "SALES_EXECUTIVE")
)

# --- Add Year-Month ---
df["INVOICE_DATE"] = pd.to_datetime(df["INVOICE_DATE"], errors="coerce")
df["YearMonth"] = df["INVOICE_DATE"].dt.to_period("M").astype(str)

# --- Monthly Breakdown Function ---
def monthly_breakdown(subdf):
    total_val = subdf["ITEM_VALUE_INCL_TAX"].sum()
    total_qty = subdf["NU_PRODUCT_QUANTITY"].sum()
    return {
        ym: {
            "Quantity %": round(qty / total_qty * 100, 2) if total_qty else 0,
            "Value %": round(val / total_val * 100, 2) if total_val else 0
        }
        for ym, (qty, val) in (
            subdf.groupby("YearMonth")[ ["NU_PRODUCT_QUANTITY", "ITEM_VALUE_INCL_TAX"] ]
            .sum()
            .iterrows()
        )
    }

# --- Apply monthly breakdown per product ---
product_summary["monthly_breakdown"] = product_summary["PRODUCT_NAME"].apply(
    lambda p: monthly_breakdown(df[df["PRODUCT_NAME"] == p])
)

# --- Final Output (Top 10 + Bottom 10) ---
output_df = product_summary

print(output_df)
